pragma solidity 0.8.24;

import 'forge-std/Test.sol';

contract OperatorPrecedenceTest is Test {
    function test_zerDepositsPassValidation() public pure {
        uint256 deposit0 = 0;
        uint256 deposit1 = 0;

        // Bug: evaluates as deposit0 | (deposit1 == 0)
        bool buggyCondition = (deposit0 | deposit1 == 0) != 0;
        // Intent: evaluates as (deposit0 | deposit1) == 0
        bool correctCondition = ((deposit0 | deposit1) == 0);

        // Buggy: zero deposits are treated as non-zero (passes validation)
        assertTrue(buggyCondition, 'Bug: zero deposits pass validation');
        // Correct: zero deposits would be caught
        assertTrue(correctCondition, 'Correct: zero deposits are zero');
    }

    function test_token1OnlyDepositBlocked() public pure {
        uint256 deposit0 = 0;
        uint256 deposit1 = 1000e18;

        // Bug: 0 | (1000e18 == 0) = 0 | false = 0 | 0 = 0 -> reverts
        bool buggyResult = deposit0 | deposit1 == 0;
        assertEq(buggyResult, false, 'Token1-only blocked by bug');

        // Correct: (0 | 1000e18) == 0 -> false -> no revert
        bool correctResult = (deposit0 | deposit1) == 0;
        assertFalse(correctResult, 'Token1-only should be valid');
    }

    function test_token0OnlyAccepted() public pure {
        uint256 deposit0 = 1000e18;
        uint256 deposit1 = 0;

        // Bug: 1000e18 | (0 == 0) = 1000e18 | 1 = non-zero -> passes
        bool buggyResult = (deposit0 | deposit1 == 0) != 0;
        assertTrue(buggyResult, 'Token0-only passes (asymmetric)');
    }

