import 'forge-std/Test.sol';
import {FullMath} from '../lib/tm-core-lib/src/utils/math/FullMath.sol';

contract DivisionByZeroTest is Test {
    uint256 constant MAX_BPS = 10_000;
    uint256 constant DOUBLE_BPS = MAX_BPS * MAX_BPS;

    function test_denominatorIsZero() public pure {
        uint16 poolFeeBPS = uint16(MAX_BPS);  // 10000, allowed for input swaps
        uint16 lpFeeBPS = uint16(MAX_BPS);    // 10000, allowed by setProtocolFees

        uint256 denominator = DOUBLE_BPS - uint256(poolFeeBPS) * uint256(lpFeeBPS);
        assertEq(denominator, 0, 'Denominator should be exactly zero');
    }

    function test_mulDivRevertsOnZeroDenominator() public {
        uint256 shortage = 1e18;
        uint256 denominator = 0;

        vm.expectRevert(); // FullMath__MulDivOverflowError
        FullMath.mulDivRoundingUp(shortage, DOUBLE_BPS, denominator);
    }

