// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import 'forge-std/Test.sol';

contract HookFeeOverflowTest is Test {
    function test_hookFeeAdditionOverflowToSmallValue() public pure {
        // Two malicious hooks each return values that sum to overflow
        uint256 tokenInTokenInFee = type(uint256).max - 100;
        uint256 tokenOutTokenInFee = 200;
        uint256 amount = 1000e18;

        unchecked {
            // Overflows: max-100 + 200 = 99 (wrapped)
            uint256 totalHookFees = tokenInTokenInFee + tokenOutTokenInFee;
            assertEq(totalHookFees, 99, 'Sum should overflow to 99');

            // amount -= 99 = nearly unchanged, masking the massive real fees
            amount -= totalHookFees;
            assertGt(amount, 900e18, 'Amount barely changed despite huge fees');
        }
    }

    function test_hookFeeOverflowToZero() public pure {
        // Exact overflow to zero
        uint256 tokenInTokenInFee = type(uint256).max / 2 + 1;
        uint256 tokenOutTokenInFee = type(uint256).max / 2 + 1;
        uint256 amount = 1000e18;

        unchecked {
            uint256 totalHookFees = tokenInTokenInFee + tokenOutTokenInFee;
            assertEq(totalHookFees, 0, 'Sum overflows to exactly 0');

            amount -= totalHookFees;
            assertEq(amount, 1000e18, 'Amount unchanged — pool fee hook sees full amount');
        }
    }

